#include <chrono>
#include <filesystem>
#include <iostream>

#include "ddb/recovery/redo_engine.h"

int main(){try{const auto database=std::filesystem::temp_directory_path()/"ddb_redo_benchmark.db";std::error_code error;std::filesystem::remove(database,error);std::filesystem::remove(database.string()+".wal",error);ddb::storage::LogManager log(database.string()+".wal");constexpr std::size_t mutations=100; (void)log.append_begin(1);for(std::size_t index=0;index<mutations;++index){(void)log.append_page_allocate(1,ddb::storage::PageId(index));std::vector<std::byte> image(ddb::storage::kPagePayloadSize,std::byte(static_cast<unsigned char>(index)));ddb::storage::PhysicalMutation mutation{ddb::storage::PageId(index),ddb::storage::MutationKind::PayloadWrite,index,std::vector<std::byte>(ddb::storage::kPagePayloadSize),std::move(image)};(void)log.append_physical_mutation(1,mutation);}(void)log.append_commit(1);log.flush();auto state=ddb::recovery::RecoveryAnalyzer::analyze(log);ddb::storage::PageManager pages(database);ddb::buffer::BufferPoolManager pool(pages,128,&log);ddb::recovery::ReplayContext replay(pages,pool);const auto start=std::chrono::steady_clock::now();const auto metrics=ddb::recovery::RedoEngine::run(state,replay);const auto elapsed=std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-start);std::cout<<"REDO benchmark: wal_bytes="<<state.metrics.wal_bytes_scanned<<", records="<<state.metrics.total_records<<", mutations="<<metrics.physical_mutations_considered<<", applied="<<metrics.mutations_applied<<", skipped="<<metrics.mutations_skipped_page_lsn<<", duration_us="<<elapsed.count()<<"\n";std::filesystem::remove(database,error);std::filesystem::remove(database.string()+".wal",error);}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
